contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need an ERC20 holder to transfer mAsset into c. The test contract itself will act as msg.sender
    // for calls into c. The run function takes an amount and a recipient 'to'.
    function run(uint256 mAssetAmount, address to) public payable {
        require(mAssetAmount > 0, "need positive amount");
        // read pre-state: exchangeRate and balanceOfToken(to)
        uint256 exchangeRateBefore = c.savings().exchangeRate();
        uint256 balanceTokenBefore = c.balanceOfToken(to);

        // The test contract must hold mAsset and approve c to pull it via safeTransferFrom.
        // We observe only through c's public surface, so we attempt the call and record if it reverted.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 exchangeRateAfter = c.savings().exchangeRate();
        uint256 balanceTokenAfter = c.balanceOfToken(to);

        // If the call reverted then nothing in c's state should have changed: balanceOfToken must be unchanged.
        // If it succeeded, then compute minimal expected increase assuming creditsIssued * exchangeRate/1e18
        // Since we cannot observe creditsIssued directly, we use the change in balanceOfToken as observable.
        // Assert general rule: either reverted and no change, or succeeded and balance increased by at least 0.
        // (This captures that supply cannot decrease beneficiary's token balance.)
        assert(
            (reverted && balanceTokenAfter == balanceTokenBefore)
            || (!reverted && balanceTokenAfter >= balanceTokenBefore)
        );
    }

    receive() external payable {}
}

