contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try calling supplyTokenTo and check that beneficiary's
    // balanceOfToken does not decrease (in terms of mAssets computed by c.balanceOfToken)
    // for any caller-supplied mAssetAmount and beneficiary address.
    function run(uint256 mAssetAmount, address beneficiary) public payable {
        require(beneficiary != address(0));
        // Read before-view of beneficiary underlying balance
        uint256 before = c.balanceOfToken(beneficiary);

        // We need to have the test contract supply mAssets to c. The deployed C expects
        // msg.sender to have approved and to transferFrom; but per problem constraints,
        // the checker deploys a fresh c and this contract deployed c, so this contract
        // can call supplyTokenTo and rely on mAsset.safeTransferFrom to move tokens only
        // if token allows it. We must still call and catch reverts.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, beneficiary) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-view
        uint256 after = c.balanceOfToken(beneficiary);

        // General rule: if the call did not revert, beneficiary's underlying balance (as reported
        // by balanceOfToken) is >= before. If the call reverted, no requirement about balances.
        assert(reverted || after >= before);
    }

    receive() external payable {}
}

