contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: caller supplies mAssetAmount and recipient 'to'
    function run(address to, uint256 mAssetAmount) public payable {
        require(mAssetAmount > 0, "need positive amount");

        // Observe exchange rate before
        uint256 rateBefore = c.savings().exchangeRate();
        // Observe reported underlying balance for 'to' before
        uint256 balBefore = c.balanceOfToken(to);

        // The test contract must hold enough mAsset to transfer; we can't mint, but
        // the checker deploys a fresh c and this contract is the deployer of c, so
        // to make the transfer succeed in verifier, we conservatively try the call
        // and capture if it reverts. We must call supplyTokenTo as top-level statement.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe exchange rate and balance after (always via public/view)
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balAfter = c.balanceOfToken(to);

        // General rule: If the call succeeded (did not revert), then the balanceOfToken(to)
        // must have increased by a non-negative amount that equals (creditsIssued * rateAfter)/1e18.
        // We cannot read creditsIssued directly, but the contract's logic makes imBalances[to]
        // increase by exactly creditsIssued and balanceOfToken computes (imBalances[to]*exchangeRate)/1e18.
        // Therefore, when call succeeds and exchangeRate did not underflow, the following holds:
        // balAfter * 1e18 >= balBefore * 1e18 and the delta equals an integer multiple of rateAfter.

        // To keep the assertion fully observable, state the rule: if not reverted then
        // balAfter >= balBefore and (balAfter - balBefore) * 1e18 == ((balAfter * 1e18) - (balBefore * 1e18))
        // (this tautology ensures using observed values) but we must assert a meaningful relationship.
        // We assert: if call succeeded then balAfter >= balBefore, and if exchange rate stayed the same
        // then the increase scaled by 1e18 is divisible by rateAfter (i.e., corresponds to integer credits).

        if (!reverted) {
            // Ensure non-decreasing underlying balance for recipient when supply succeeds
            // Also require that balAfter >= balBefore holds
            assert(balAfter >= balBefore && (
                // if rateAfter == 0 we cannot check divisibility; accept only non-decreasing then
                (rateAfter == 0) || ((balAfter - balBefore) * 1e18 % rateAfter == 0)
            ));
        } else {
            // If reverted, there is no further requirement; still assert that balances unchanged when revert
            assert(balAfter == balBefore);
        }
    }

    receive() external payable {}
}

