contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function with inputs: amount to supply and beneficiary
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "beneficiary nonzero");
        // Ensure the test contract has enough mAsset to transfer: we can only observe via c's public interface.
        // We will call supplyTokenTo and check observable invariants. The caller (this contract) must have approved c to pull tokens
        // but we cannot perform ERC20 approve here because IERC20 isn't redeclared; however the environment that runs the prover
        // will consider arbitrary inputs and allow non-revert path. We therefore allow both revert and non-revert paths and assert
        // a relation that must hold when the call does not revert.

        // Read imBalances[to] before
        uint256 beforeCredits = c.imBalances(to);
        // Read address(c).balance before for later observation (though supplyTokenTo doesn't transfer Ether)
        uint256 befBal = address(c).balance;

        bool reverted;
        // perform the state-changing call at top-level and capture whether it reverted
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
