contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We need to interact with the mAsset token used by c, but per constraints we may only
    // observe c through its public surface. We'll call supplyTokenTo and then redeemToken and
    // assert that the caller cannot redeem more mAssets than were previously observed to be
    // credited to it (i.e., you can't get more underlying out than the token balance change of c
    // when redeeming for yourself). The property: for any caller, after a supplyTokenTo and
    // immediately redeemToken by that same caller, the mAssets actually transferred back by
    // redeemToken cannot exceed the mAsset balance that c had increased by when receiving the
    // supplied amount. To achieve this we act as msg.sender by calling through this contract.

    // single public entry point with parameters controlling amounts and target
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0));

        // Record c's view of the "to" balance in underlying before any action
        uint256 beforeUnderlying = c.balanceOfUnderlying(to);

        // We will attempt a supply from this contract to `to` using supplyTokenTo.
        // As the test contract is msg.sender for c calls, we must call supplyTokenTo directly.
        // The call may revert if transferFrom fails; capture revert and still assert a general rule.
        bool supplyReverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            supplyReverted = false;
        } catch {
            supplyReverted = true;
        }

        // After the attempt, record the new underlying balance for `to` and the contract's own
        // ability to redeem (if any). We will also attempt to redeem from this contract if `to` == address(this).
        uint256 afterUnderlying = c.balanceOfUnderlying(to);

        bool redeemReverted;
        uint256 redeemedActual = 0;
        if (to == address(this)) {
            // try to redeem the same nominal amount we supplied; redeemToken returns mAssetsActual
            try c.redeemToken(mAssetAmount) returns (uint256 mAssetsActual) {
                redeemReverted = false;
                redeemedActual = mAssetsActual;
            } catch {
                redeemReverted = true;
            }
        } else {
            // If not redeeming as this contract, we still set flags consistently
            redeemReverted = true;
            redeemedActual = 0;
        }

        // General rule asserted:
        // If supply succeeded and then this contract (when acting as the beneficiary) redeemed, the
        // actual mAssets received by redeemToken cannot exceed the increase in c's view of the
        // underlying balance for this contract (i.e., you can't redeem more underlying than the
        // underlying balance increment observed after a successful supply). If supply reverted,
        // no redeem by this contract should have succeeded producing positive mAssets.
        assert(
            // Case A: supply reverted -> redeem must not have produced positive mAssets
            (supplyReverted && redeemedActual == 0)
            ||
            // Case B: supply succeeded and we performed a redeem as this contract -> redeemedActual <= afterUnderlying - beforeUnderlying
            (!supplyReverted && to == address(this) && !redeemReverted && redeemedActual <= (afterUnderlying + (uint256(0)) - beforeUnderlying))
            ||
            // Case C: supply succeeded but we did not attempt redeem as this contract -> nothing to check about redeemedActual
            (!supplyReverted && to != address(this))
        );
    }

    // allow receiving ETH though not used
    receive() external payable {}
}

