    // params: mAssetAmount to supply, and recipient address 'to'
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "to nonzero");
        // read exchangeRate before call
        uint256 rateBefore = c.savings().exchangeRate();
        // read recipient balanceOfToken before (view)
        uint256 balBefore = c.balanceOfToken(to);

        bool reverted;
        // perform supplyTokenTo; since supplyTokenTo does a transferFrom, the call will usually revert
        // because this contract has no approval or tokens, so we catch reverts and record that.
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read exchangeRate and balance after
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balAfter = c.balanceOfToken(to);

        // If the call did not revert, then the recipient's balanceOfToken (in mAssets) must have increased by at least
        // the nominal underlying converted using the pre-call exchange rate: (mAssetAmount * rateBefore) / 1e18
        // We express this as balAfter >= balBefore + (mAssetAmount * rateBefore) / 1e18
        // If reverted, no guarantee — so allow any outcome. Also allow for rate change by using rateBefore for expected minimum.
        if (!reverted) {
            // avoid overflow in multiplication by using checked multiplication via require earlier would revert; but here use assert with condition
            uint256 expectedIncrease = (mAssetAmount * rateBefore) / 1e18;
            assert(balAfter >= balBefore + expectedIncrease);
        } else {
            // If reverted, assert a trivial relational property comparing rates and balances to ensure assert is reachable
            // (must still be a general property: when revert happens, nothing required about balances — so assert that either rate unchanged or balances unchanged)
            assert(rateAfter == rateBefore || balAfter == balBefore);
        }
    }

    receive() external payable {}
}

