    // We cannot declare interfaces, but the existing compilation unit already has IERC20.
    // The test will assume the caller provides a token amount via params and that this contract
    // has been approved by the test harness to transfer tokens from msg.sender to c where needed.

    function run(address from, address to, uint256 mAssetAmount) public payable {
        require(from != address(0) && to != address(0));

        // Capture pre-call observable state
        uint256 imBefore = c.imBalances(to);
        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 balanceTokenBefore = c.mAsset().balanceOf(address(c));

        // Perform the state-changing call: supplyTokenTo
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observable post-call values
        uint256 imAfter = c.imBalances(to);
        uint256 balanceTokenAfter = c.mAsset().balanceOf(address(c));
        uint256 imDelta = imAfter - imBefore;

        // If the call succeeded (didn't revert), then:
        // - c.imBalances(to) must have increased by some number of credits (possibly zero only if mAssetAmount==0)
        // - c.mAsset balance should be >= before (since supplyTokenTo transfers tokens into c then deposits to savings)
        // - balanceOfToken view must equal (imBalances[to] * exchangeRate) / 1e18
        bool postViewMatches = (c.balanceOfToken(to) == (imAfter * exchangeRate) / 1e18);

        assert(
            // Either the call reverted, or all the observable invariants hold
            reverted || (
                // imBalances increased by exactly the credits returned by savings.depositSavings is an internal detail we can't read,
                // but we can assert non-decrease for positive deposit and that the on-chain token balance did not decrease.
                // For generality allow zero amount deposits: in that case imDelta==0 is acceptable.
                imAfter >= imBefore
                && balanceTokenAfter >= balanceTokenBefore - 1 /* allow 1 wei fuzz for edge interactions */
                && postViewMatches
            )
        );
    }

    receive() external payable {}
}

