contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take as inputs: amount to supply and the recipient address.
    // The test will transfer ERC20 tokens into c by calling c.supplyTokenTo(amount, to).
    // Because this test contract is the deployer of c, msg.sender for calls from this test
    // to c is this contract. We only interact via c's external functions and public getters.
    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0));
        // Pre-read observable values
        uint256 rateBefore = c.savings().exchangeRate();
        // imBalances is public, get via autogenerated getter
        uint256 creditsBefore = c.imBalances(to);
        uint256 balanceTokenBefore = c.balanceOfToken(to);

        // We need to have tokens approved and available for transferFrom by c. The contract C's constructor
        // approved the savings contract to spend mAsset but did not approve this test. However the I/O model
        // for the checker provides arbitrary inputs; we cannot mint tokens here. To make a valid top-level state change
        // that will compile and the checker can reason about, we call supplyTokenTo but it may revert if transferFrom fails.
        // We'll catch whether it reverted.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call (successful or reverted), read observables again
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 creditsAfter = c.imBalances(to);
        uint256 balanceTokenAfter = c.balanceOfToken(to);

        // General property to assert:
        // If the supply did not revert, then the recipient's imBalances (credits) must have increased or stayed the same,
        // and the reported underlying balanceOfToken should be >= previous balance, computed using the (conservative) min of exchange rates.
        // We avoid underflow by using comparisons only.
        assert(
            // If reverted, we make no claim about balances (the property trivially holds as a relation between same-values)
            reverted
            || (
                // credits must not decrease
                creditsAfter >= creditsBefore
                // and balanceOfToken must not decrease when interpreted with the observed exchange rates:
                // since balanceOfToken uses current savings.exchangeRate(), we require balanceTokenAfter >= balanceTokenBefore
                && balanceTokenAfter >= balanceTokenBefore
                // and the exchange rate should not have decreased (savings.exchangeRate is expected to be non-decreasing across this single operation)
                && rateAfter >= rateBefore
            )
        );
    }

    // receive to accept any ETH if necessary
    receive() external payable {}
}

