        // Attempt the state-changing call and record whether it reverted
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.balanceOfToken(to);

        // General rule: if the call did not revert then afterBal >= beforeBal
        assert(reverted || afterBal >= beforeBal);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters
    function run(address to, uint256 mAssetAmount) public payable {
        require(to != address(0), "to nonzero");
        require(mAssetAmount > 0, "amount>0");

        // Observe exchange rate and balance of the 'to' address in mAsset units before
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balTokenBefore = c.balanceOfToken(to);

        // We will attempt to call supplyTokenTo as msg.sender = this contract.
        // The call will transferFrom tokens from this contract; ensure call can proceed by
        // performing a safeTransferFrom simulation is not possible here, but we just call and record if it reverts.
        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe exchange rate and balance after
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balTokenAfter = c.balanceOfToken(to);

        // General invariant: If the call did not revert, then the balanceOfToken for `to` must not be less than before.
        // (Supplying should not decrease beneficiary's token balance as observed in underlying mAsset units.)
        // Also, exchangeRate should remain >=0 (always true) but we relate balances using non-decreasing property.
        assert(reverted || balTokenAfter >= balTokenBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: for any mAssetAmount, redeemToken either reverts or transfers that many mAssets (non-negative) to the caller
    function run(uint256 mAssetAmount) public payable {
        // Observe balances and imBalances-equivalent via public view
        uint256 beforeBal = c.mAsset().balanceOf(address(this));
        uint256 creditsBefore; // can't read imBalances directly, but we can observe balanceOfToken for this address
        creditsBefore = c.balanceOfToken(address(this));

        bool didRevert;
        uint256 returned;
        // Make the state-changing call as a top-level statement and catch revert
        try c.redeemToken(mAssetAmount) returns (uint256 ret) {
            didRevert = false;
            returned = ret;
        } catch {
            didRevert = true;
            returned = 0;
        }

        uint256 afterBal = c.mAsset().balanceOf(address(this));
        uint256 balanceOfTokenAfter = c.balanceOfToken(address(this));

        // General rule:
        // If redeemToken did not revert then:
        //  - afterBal >= beforeBal (caller received non-negative mAssets)
        //  - the observed increase in mAsset balance equals the returned value
        //  - imBalances (as observed through balanceOfToken) did not increase
        assert(didRevert || (afterBal >= beforeBal && afterBal - beforeBal == returned && balanceOfTokenAfter <= creditsBefore));
    }

    receive() external payable {}
}
